async function run(items) {
  for (const item of items) {
    const res = await llm.messages.create({ model: 'any-model', max_tokens: 512, messages: [{ role: 'user', content: item.text }] })
    await save(item.id, res)
  }
}
export { run }

import { llm } from '../src/lib/llm-client'
async function run(items) {
  const requests = items.map(item => ({ custom_id: item.id, params: { model: 'any-model', max_tokens: 512, messages: [{ role: 'user', content: item.text }] } }))
  return llm.messages.batches.create({ requests })
}
